@'
import assert from 'node:assert/strict';
import {readFileSync,existsSync,readdirSync} from 'node:fs';
import {resolve,dirname} from 'node:path';
import {parseManifest} from './packages/core/src/domain/manifest.ts';
import {parseSkillDocument,documentName,documentDescription} from './packages/core/src/domain/skill-document.ts';
const root=resolve('skills/jfr-and-async-profiler');
const parsed=parseManifest(readFileSync(resolve(root,'skill.yaml'),'utf8'),{strict:true});
assert.deepEqual(parsed.issues,[]);
const doc=parseSkillDocument(readFileSync(resolve(root,'SKILL.md'),'utf8'));
assert.equal(documentName(doc),parsed.manifest.name);
const normalize=s=>s.replace(/\s+/g,' ').trim();
assert.equal(normalize(documentDescription(doc)),normalize(parsed.manifest.description));
for(const file of parsed.manifest.files)assert.ok(existsSync(resolve(root,file)),file);
const files=['SKILL.md',...readdirSync(resolve(root,'references')).filter(f=>f.endsWith('.md')).map(f=>'references/'+f)];
let links=0;
for(const file of files){
 const absolute=resolve(root,file);
 for(const match of readFileSync(absolute,'utf8').matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){
  if(/^[a-z]+:/i.test(match[1]))continue;
  const [target,anchor]=match[1].split('#');
  const path=target?resolve(dirname(absolute),target):absolute;
  assert.ok(existsSync(path),match[1]);
  if(anchor){const headings=[...readFileSync(path,'utf8').matchAll(/^#{1,6}\s+(.+)$/gm)].map(m=>m[1].toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu,'').trim().replace(/\s/g,'-'));assert.ok(headings.includes(anchor),match[1]);}
  links++;
 }
}
console.log(JSON.stringify({name:parsed.manifest.name,version:parsed.manifest.version,issues:parsed.issues,descriptionEqual:true,markdownFiles:files.length,localLinksAndAnchors:links}));
